struct rds_connection *rds_conn_create_or_get(struct net *net, __be32 laddr,
					      __be32 faddr,
					      struct rds_transport *trans,
					      gfp_t gfp, int is_outgoing)
{
	struct rds_connection *conn;

	conn = rds_conn_find(laddr, faddr);
	if (conn)
		return conn;

	conn = kzalloc(trans->t_conn_size, gfp);
	if (!conn)
		return ERR_PTR(-ENOMEM);

	conn->c_laddr = laddr;
	conn->c_faddr = faddr;
	conn->c_trans = trans;
	conn->c_net = *net;
	conn->c_is_outgoing = is_outgoing;

	if (is_outgoing) {
		if (laddr == 0)
			conn->c_laddr = faddr;
	} else {
		if (conn->c_laddr == conn->c_faddr) {
			kfree(conn);
			return ERR_PTR(-EINVAL);
		}
	}

	rds_atomic_inc(&rds_conn_count);
	spin_lock(&rds_connection_lock);
	hlist_add_head(&conn->c_list, &rds_connection_table);
	spin_unlock(&rds_connection_lock);

	return conn;
}

struct rds_connection *rds_conn_create(struct net *net, __be32 laddr, __be32 faddr,
                                      struct rds_transport *trans, gfp_t gfp,
                                      int is_outgoing)
{
    struct rds_connection *conn;

    conn = rds_conn_lookup(laddr, faddr, is_outgoing);
    if (conn)
        return conn;

    conn = kzalloc(trans->t_conn_size, gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    conn->c_laddr = laddr;
    conn->c_faddr = faddr;
    conn->c_transport = trans;
    conn->c_is_outgoing = is_outgoing;
    conn->c_net = net;

    spin_lock_init(&conn->c_lock);
    mutex_init(&conn->c_tx_lock);
    mutex_init(&conn->c_rx_lock);

    if (is_outgoing) {
        conn->c_state = RDS_CONN_CONNECTING;
    } else {
        conn->c_state = RDS_CONN_ESTABLISHED;
        rds_conn_add(conn);
    }

    return conn;
}

struct rds_connection *rds_conn_create_or_get(struct net *net, __be32 laddr, __be32 faddr,
                                             struct rds_transport *trans, gfp_t gfp,
                                             int is_outgoing)
{
    struct rds_connection *conn;

    /* Check for an existing connection */
    conn = rds_conn_find(laddr, faddr, trans);
    if (conn)
        return conn;

    /* Allocate memory for a new connection */
    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    /* Initialize the connection */
    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->trans = trans;
    conn->is_outgoing = is_outgoing;

    /* Initialize other fields and setup parameters */
    atomic_set(&conn->refcount, 1);
    spin_lock_init(&conn->spinlock);

    /* Handle loopback connection if necessary */
    if (laddr == faddr) {
        conn->loopback = 1;
        rds_loopback_connection_init(conn);
    }

    /* Add the connection to the appropriate data structures with concurrency handling */
    spin_lock(&rds_conn_table_lock);
    rds_conn_add_to_table(conn);
    spin_unlock(&rds_conn_table_lock);

    return conn;
}

struct rds_connection *rds_conn_create(struct net *net, __be32 laddr, __be32 faddr,
                                      struct rds_transport *trans, gfp_t gfp,
                                      int is_outgoing)
{
    struct rds_connection *conn;
    int err;

    /* Check for an existing connection */
    conn = rds_conn_find(laddr, faddr);
    if (conn)
        return conn;

    /* Allocate memory for a new connection */
    conn = kzalloc(sizeof(*conn), gfp);
    if (!conn)
        return ERR_PTR(-ENOMEM);

    /* Initialize connection parameters */
    conn->laddr = laddr;
    conn->faddr = faddr;
    conn->trans = trans;
    conn->net = net;
    conn->is_outgoing = is_outgoing;

    /* Handle loopback connections */
    if (laddr == faddr) {
        err = rds_loopback_connect(conn);
        if (err) {
            kfree(conn);
            return ERR_PTR(err);
        }
    }

    /* Add to appropriate data structures with lock protection */
    spin_lock(&rds_conn_lock);
    list_add(&conn->list, &net->rds_conns);
    spin_unlock(&rds_conn_lock);

    return conn;
}
